-- CEO analytics pipeline: governed datasets, KPI rules, analysis, alerts and scenarios.
create table public.ceo_datasets(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.ceo_organisations(id) on delete cascade,name text not null,source_filename text not null,sheet_name text not null,row_count integer not null check(row_count between 1 and 5000),column_schema jsonb not null,rows jsonb not null check(jsonb_typeof(rows)='array'),quality_summary jsonb not null,uploaded_by uuid not null references auth.users(id),uploaded_at timestamptz not null default now());
create table public.ceo_kpi_definitions(id bigint generated by default as identity primary key,organisation_id uuid not null references public.ceo_organisations(id) on delete cascade,dataset_id uuid not null references public.ceo_datasets(id) on delete cascade,name text not null,value_column text not null,period_column text,target numeric,direction text not null default 'higher' check(direction in('higher','lower')),unit text not null default 'number' check(unit in('number','percent','currency')),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(organisation_id,name));
create table public.ceo_analysis_snapshots(id bigint generated by default as identity primary key,organisation_id uuid not null references public.ceo_organisations(id) on delete cascade,dataset_id uuid not null references public.ceo_datasets(id) on delete cascade,analysis_type text not null check(analysis_type in('descriptive','trend')),title text not null,findings jsonb not null,interpretation text not null,generated_by uuid not null references auth.users(id),generated_at timestamptz not null default now());
create table public.ceo_risk_alerts(id bigint generated by default as identity primary key,organisation_id uuid not null references public.ceo_organisations(id) on delete cascade,kpi_definition_id bigint references public.ceo_kpi_definitions(id) on delete cascade,severity text not null check(severity in('information','watch','critical')),title text not null,evidence text not null,recommended_action text not null,status text not null default 'open' check(status in('open','acknowledged','closed')),created_at timestamptz not null default now());
create table public.ceo_scenarios(id bigint generated by default as identity primary key,organisation_id uuid not null references public.ceo_organisations(id) on delete cascade,name text not null,metric_name text not null,baseline numeric not null,change_percent numeric not null check(change_percent between -100 and 1000),projected numeric not null,assumption text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create index ceo_datasets_org_idx on public.ceo_datasets(organisation_id,uploaded_at desc);create index ceo_datasets_uploader_idx on public.ceo_datasets(uploaded_by);create index ceo_kpis_org_idx on public.ceo_kpi_definitions(organisation_id);create index ceo_kpis_dataset_idx on public.ceo_kpi_definitions(dataset_id);create index ceo_kpis_creator_idx on public.ceo_kpi_definitions(created_by);create index ceo_analysis_org_idx on public.ceo_analysis_snapshots(organisation_id,generated_at desc);create index ceo_analysis_dataset_idx on public.ceo_analysis_snapshots(dataset_id);create index ceo_analysis_generator_idx on public.ceo_analysis_snapshots(generated_by);create index ceo_alerts_org_idx on public.ceo_risk_alerts(organisation_id,status,severity);create index ceo_alerts_kpi_idx on public.ceo_risk_alerts(kpi_definition_id);create index ceo_scenarios_org_idx on public.ceo_scenarios(organisation_id,created_at desc);create index ceo_scenarios_creator_idx on public.ceo_scenarios(created_by);
alter table public.ceo_datasets enable row level security;alter table public.ceo_kpi_definitions enable row level security;alter table public.ceo_analysis_snapshots enable row level security;alter table public.ceo_risk_alerts enable row level security;alter table public.ceo_scenarios enable row level security;
create or replace function private.ceo_has_role(p_org uuid,p_roles text[])returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.ceo_memberships where organisation_id=p_org and user_id=auth.uid() and active and role=any(p_roles))$$;revoke all on function private.ceo_has_role(uuid,text[])from public,anon;grant execute on function private.ceo_has_role(uuid,text[])to authenticated;
create policy "members read datasets" on public.ceo_datasets for select to authenticated using(private.ceo_has_role(organisation_id,array['ceo','executive','analyst','viewer']));create policy "analysts insert datasets" on public.ceo_datasets for insert to authenticated with check(uploaded_by=(select auth.uid()) and private.ceo_has_role(organisation_id,array['ceo','executive','analyst']));
create policy "members read kpis" on public.ceo_kpi_definitions for select to authenticated using(private.ceo_has_role(organisation_id,array['ceo','executive','analyst','viewer']));create policy "analysts insert kpis" on public.ceo_kpi_definitions for insert to authenticated with check(created_by=(select auth.uid()) and private.ceo_has_role(organisation_id,array['ceo','executive','analyst']));create policy "analysts update kpis" on public.ceo_kpi_definitions for update to authenticated using(private.ceo_has_role(organisation_id,array['ceo','executive','analyst']))with check(created_by=(select auth.uid()) and private.ceo_has_role(organisation_id,array['ceo','executive','analyst']));
create policy "members read analyses" on public.ceo_analysis_snapshots for select to authenticated using(private.ceo_has_role(organisation_id,array['ceo','executive','analyst','viewer']));create policy "analysts insert analyses" on public.ceo_analysis_snapshots for insert to authenticated with check(generated_by=(select auth.uid()) and private.ceo_has_role(organisation_id,array['ceo','executive','analyst']));
create policy "members read alerts" on public.ceo_risk_alerts for select to authenticated using(private.ceo_has_role(organisation_id,array['ceo','executive','analyst','viewer']));create policy "analysts insert alerts" on public.ceo_risk_alerts for insert to authenticated with check(private.ceo_has_role(organisation_id,array['ceo','executive','analyst']));
create policy "members read scenarios" on public.ceo_scenarios for select to authenticated using(private.ceo_has_role(organisation_id,array['ceo','executive','analyst','viewer']));create policy "executives insert scenarios" on public.ceo_scenarios for insert to authenticated with check(created_by=(select auth.uid()) and private.ceo_has_role(organisation_id,array['ceo','executive']));
grant select on public.ceo_datasets,public.ceo_kpi_definitions,public.ceo_analysis_snapshots,public.ceo_risk_alerts,public.ceo_scenarios to authenticated;grant insert on public.ceo_datasets,public.ceo_kpi_definitions,public.ceo_analysis_snapshots,public.ceo_risk_alerts,public.ceo_scenarios to authenticated;grant update on public.ceo_kpi_definitions to authenticated;grant usage,select on sequence public.ceo_kpi_definitions_id_seq,public.ceo_analysis_snapshots_id_seq,public.ceo_risk_alerts_id_seq,public.ceo_scenarios_id_seq to authenticated;
